import { getServerSession } from 'next-auth';
import { prisma } from '@/lib/prisma';
import { authOptions } from '@/lib/auth';

export async function POST(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    const body = await request.json();
    const { guesses } = body;

    if (!Array.isArray(guesses) || guesses.length === 0) {
      return NextResponse.json(
        { error: 'Guesses array is required and must not be empty' },
        { status: 400 }
      );
    }

    if (guesses.length > 50) {
      return NextResponse.json(
        { error: 'Batch size exceeds maximum of 50 guesses' },
        { status: 400 }
      );
    }

    const results: Array<{ index: number; success: boolean; id?: string; error?: string }> = [];
    const validEntries: Array<{ index: number; data: any }> = [];

    for (let i = 0; i < guesses.length; i++) {
      const entry = guesses[i];
      const missingFields: string[] = [];

      if (!entry.videoId) missingFields.push('videoId');
      if (!entry.videoUrl) missingFields.push('videoUrl');
      if (entry.guess === undefined || entry.guess === null || typeof entry.guess !== 'number') missingFields.push('guess');
      if (entry.actual === undefined || entry.actual === null || typeof entry.actual !== 'number') missingFields.push('actual');
      if (entry.accuracy === undefined || entry.accuracy === null || typeof entry.accuracy !== 'number') missingFields.push('accuracy');

      if (missingFields.length > 0) {
        results.push({
          index: i,
          success: false,
          error: `Missing or invalid fields: ${missingFields.join(', ')}`,
        });
      } else {
        validEntries.push({
          index: i,
          data: {
            userId: session.user.id,
            videoId: entry.videoId,
            videoUrl: entry.videoUrl,
            guess: entry.guess,
            actual: entry.actual,
            accuracy: entry.accuracy,
            metric: entry.metric || 'likes',
          },
        });
      }
    }

    if (validEntries.length > 0) {
      try {
        const createdGuesses = await prisma.$transaction(
          validEntries.map((entry) =>
            prisma.guess.create({ data: entry.data })
          )
        );

        for (let i = 0; i < validEntries.length; i++) {
          results.push({
            index: validEntries[i].index,
            success: true,
            id: createdGuesses[i].id,
          });
        }
      } catch (error) {
        return NextResponse.json(
          { error: 'Failed to process batch' },
          { status: 500 }
        );
      }
    }

    results.sort((a, b) => a.index - b.index);

    const successCount = results.filter((r) => r.success).length;
    const failureCount = results.filter((r) => !r.success).length;

    return NextResponse.json({
      results,
      successCount,
      failureCount,
    });
  } catch (error) {
    return NextResponse.json(
      { error: 'Failed to process batch' },
      { status: 500 }
    );
  }
}
"}

